-- Durable automatic achievements. No source records are changed.
CREATE TABLE IF NOT EXISTS hub_achievement_events (
 squad_id TEXT NOT NULL, member_id TEXT NOT NULL, metric TEXT NOT NULL,
 event_key TEXT NOT NULL, occurred_at TEXT NOT NULL,
 PRIMARY KEY(squad_id,member_id,metric,event_key)
);
CREATE INDEX IF NOT EXISTS hub_achievement_member ON hub_achievement_events(squad_id,member_id,metric,occurred_at);
CREATE UNIQUE INDEX IF NOT EXISTS hub_achievement_source ON hub_achievement_events(squad_id,metric,event_key) WHERE metric IN ('stash','marker','vehicle','enemy','task','refresh');


INSERT OR IGNORE INTO hub_achievement_events(squad_id,member_id,metric,event_key,occurred_at) SELECT squad_id,member_id,'presence',day,COALESCE(updated_at,strftime('%Y-%m-%dT%H:%M:%fZ','now')) FROM presence_history WHERE member_id IS NOT NULL AND day IS NOT NULL AND (status IN ('Буду','Не буду','Под вопросом')) AND EXISTS(SELECT 1 FROM members m WHERE m.id=presence_history.member_id AND m.squad_id=presence_history.squad_id);

CREATE TRIGGER IF NOT EXISTS hub_ach_0_insert AFTER INSERT ON presence_history WHEN NEW.member_id IS NOT NULL AND NEW.day IS NOT NULL AND (NEW.status IN ('Буду','Не буду','Под вопросом')) AND EXISTS(SELECT 1 FROM members m WHERE m.id=NEW.member_id AND m.squad_id=NEW.squad_id) BEGIN INSERT OR IGNORE INTO hub_achievement_events(squad_id,member_id,metric,event_key,occurred_at) VALUES(NEW.squad_id,NEW.member_id,'presence',NEW.day,COALESCE(NEW.updated_at,strftime('%Y-%m-%dT%H:%M:%fZ','now'))); END;

CREATE TRIGGER IF NOT EXISTS hub_ach_0_update AFTER UPDATE ON presence_history WHEN NEW.member_id IS NOT NULL AND NEW.day IS NOT NULL AND (NEW.status IN ('Буду','Не буду','Под вопросом')) AND EXISTS(SELECT 1 FROM members m WHERE m.id=NEW.member_id AND m.squad_id=NEW.squad_id) BEGIN INSERT OR IGNORE INTO hub_achievement_events(squad_id,member_id,metric,event_key,occurred_at) VALUES(NEW.squad_id,NEW.member_id,'presence',NEW.day,COALESCE(NEW.updated_at,strftime('%Y-%m-%dT%H:%M:%fZ','now'))); END;

INSERT OR IGNORE INTO hub_achievement_events(squad_id,member_id,metric,event_key,occurred_at) SELECT squad_id,member_id,'ready',day,COALESCE(updated_at,strftime('%Y-%m-%dT%H:%M:%fZ','now')) FROM presence_history WHERE member_id IS NOT NULL AND day IS NOT NULL AND (status='Буду') AND EXISTS(SELECT 1 FROM members m WHERE m.id=presence_history.member_id AND m.squad_id=presence_history.squad_id);

CREATE TRIGGER IF NOT EXISTS hub_ach_1_insert AFTER INSERT ON presence_history WHEN NEW.member_id IS NOT NULL AND NEW.day IS NOT NULL AND (NEW.status='Буду') AND EXISTS(SELECT 1 FROM members m WHERE m.id=NEW.member_id AND m.squad_id=NEW.squad_id) BEGIN INSERT OR IGNORE INTO hub_achievement_events(squad_id,member_id,metric,event_key,occurred_at) VALUES(NEW.squad_id,NEW.member_id,'ready',NEW.day,COALESCE(NEW.updated_at,strftime('%Y-%m-%dT%H:%M:%fZ','now'))); END;

CREATE TRIGGER IF NOT EXISTS hub_ach_1_update AFTER UPDATE ON presence_history WHEN NEW.member_id IS NOT NULL AND NEW.day IS NOT NULL AND (NEW.status='Буду') AND EXISTS(SELECT 1 FROM members m WHERE m.id=NEW.member_id AND m.squad_id=NEW.squad_id) BEGIN INSERT OR IGNORE INTO hub_achievement_events(squad_id,member_id,metric,event_key,occurred_at) VALUES(NEW.squad_id,NEW.member_id,'ready',NEW.day,COALESCE(NEW.updated_at,strftime('%Y-%m-%dT%H:%M:%fZ','now'))); END;

INSERT OR IGNORE INTO hub_achievement_events(squad_id,member_id,metric,event_key,occurred_at) SELECT squad_id,created_by,'stash','post:'||id,COALESCE(created_at,strftime('%Y-%m-%dT%H:%M:%fZ','now')) FROM squad_place_posts WHERE created_by IS NOT NULL AND 'post:'||id IS NOT NULL AND (kind='stash') AND EXISTS(SELECT 1 FROM members m WHERE m.id=squad_place_posts.created_by AND m.squad_id=squad_place_posts.squad_id);

CREATE TRIGGER IF NOT EXISTS hub_ach_2_insert AFTER INSERT ON squad_place_posts WHEN NEW.created_by IS NOT NULL AND 'post:'||NEW.id IS NOT NULL AND (NEW.kind='stash') AND EXISTS(SELECT 1 FROM members m WHERE m.id=NEW.created_by AND m.squad_id=NEW.squad_id) BEGIN INSERT OR IGNORE INTO hub_achievement_events(squad_id,member_id,metric,event_key,occurred_at) VALUES(NEW.squad_id,NEW.created_by,'stash','post:'||NEW.id,COALESCE(NEW.created_at,strftime('%Y-%m-%dT%H:%M:%fZ','now'))); END;

CREATE TRIGGER IF NOT EXISTS hub_ach_2_update AFTER UPDATE ON squad_place_posts WHEN NEW.created_by IS NOT NULL AND 'post:'||NEW.id IS NOT NULL AND (NEW.kind='stash') AND EXISTS(SELECT 1 FROM members m WHERE m.id=NEW.created_by AND m.squad_id=NEW.squad_id) AND OLD.kind IS NOT NEW.kind BEGIN INSERT OR IGNORE INTO hub_achievement_events(squad_id,member_id,metric,event_key,occurred_at) VALUES(NEW.squad_id,NEW.created_by,'stash','post:'||NEW.id,COALESCE(NEW.created_at,strftime('%Y-%m-%dT%H:%M:%fZ','now'))); END;

INSERT OR IGNORE INTO hub_achievement_events(squad_id,member_id,metric,event_key,occurred_at) SELECT squad_id,created_by,'marker','post:'||id,COALESCE(created_at,strftime('%Y-%m-%dT%H:%M:%fZ','now')) FROM squad_place_posts WHERE created_by IS NOT NULL AND 'post:'||id IS NOT NULL AND (kind IN ('stash','base','other')) AND EXISTS(SELECT 1 FROM members m WHERE m.id=squad_place_posts.created_by AND m.squad_id=squad_place_posts.squad_id);

CREATE TRIGGER IF NOT EXISTS hub_ach_3_insert AFTER INSERT ON squad_place_posts WHEN NEW.created_by IS NOT NULL AND 'post:'||NEW.id IS NOT NULL AND (NEW.kind IN ('stash','base','other')) AND EXISTS(SELECT 1 FROM members m WHERE m.id=NEW.created_by AND m.squad_id=NEW.squad_id) BEGIN INSERT OR IGNORE INTO hub_achievement_events(squad_id,member_id,metric,event_key,occurred_at) VALUES(NEW.squad_id,NEW.created_by,'marker','post:'||NEW.id,COALESCE(NEW.created_at,strftime('%Y-%m-%dT%H:%M:%fZ','now'))); END;

INSERT OR IGNORE INTO hub_achievement_events(squad_id,member_id,metric,event_key,occurred_at) SELECT squad_id,created_by,'vehicle','post:'||id,COALESCE(created_at,strftime('%Y-%m-%dT%H:%M:%fZ','now')) FROM squad_place_posts WHERE created_by IS NOT NULL AND 'post:'||id IS NOT NULL AND (comment LIKE 'Машина:%') AND EXISTS(SELECT 1 FROM members m WHERE m.id=squad_place_posts.created_by AND m.squad_id=squad_place_posts.squad_id);

CREATE TRIGGER IF NOT EXISTS hub_ach_4_insert AFTER INSERT ON squad_place_posts WHEN NEW.created_by IS NOT NULL AND 'post:'||NEW.id IS NOT NULL AND (NEW.comment LIKE 'Машина:%') AND EXISTS(SELECT 1 FROM members m WHERE m.id=NEW.created_by AND m.squad_id=NEW.squad_id) BEGIN INSERT OR IGNORE INTO hub_achievement_events(squad_id,member_id,metric,event_key,occurred_at) VALUES(NEW.squad_id,NEW.created_by,'vehicle','post:'||NEW.id,COALESCE(NEW.created_at,strftime('%Y-%m-%dT%H:%M:%fZ','now'))); END;

INSERT OR IGNORE INTO hub_achievement_events(squad_id,member_id,metric,event_key,occurred_at) SELECT squad_id,created_by,'enemy','post:'||id,COALESCE(created_at,strftime('%Y-%m-%dT%H:%M:%fZ','now')) FROM squad_place_posts WHERE created_by IS NOT NULL AND 'post:'||id IS NOT NULL AND (kind='base' AND COALESCE(comment,'') NOT LIKE 'Машина:%') AND EXISTS(SELECT 1 FROM members m WHERE m.id=squad_place_posts.created_by AND m.squad_id=squad_place_posts.squad_id);

CREATE TRIGGER IF NOT EXISTS hub_ach_5_insert AFTER INSERT ON squad_place_posts WHEN NEW.created_by IS NOT NULL AND 'post:'||NEW.id IS NOT NULL AND (NEW.kind='base' AND COALESCE(NEW.comment,'') NOT LIKE 'Машина:%') AND EXISTS(SELECT 1 FROM members m WHERE m.id=NEW.created_by AND m.squad_id=NEW.squad_id) BEGIN INSERT OR IGNORE INTO hub_achievement_events(squad_id,member_id,metric,event_key,occurred_at) VALUES(NEW.squad_id,NEW.created_by,'enemy','post:'||NEW.id,COALESCE(NEW.created_at,strftime('%Y-%m-%dT%H:%M:%fZ','now'))); END;

INSERT OR IGNORE INTO hub_achievement_events(squad_id,member_id,metric,event_key,occurred_at) SELECT squad_id,created_by,'marker','map:'||id,COALESCE(updated_at,strftime('%Y-%m-%dT%H:%M:%fZ','now')) FROM squad_map_markers WHERE created_by IS NOT NULL AND 'map:'||id IS NOT NULL AND (id NOT GLOB '*-post-[0-9]*') AND EXISTS(SELECT 1 FROM members m WHERE m.id=squad_map_markers.created_by AND m.squad_id=squad_map_markers.squad_id);

CREATE TRIGGER IF NOT EXISTS hub_ach_6_insert AFTER INSERT ON squad_map_markers WHEN NEW.created_by IS NOT NULL AND 'map:'||NEW.id IS NOT NULL AND (NEW.id NOT GLOB '*-post-[0-9]*') AND EXISTS(SELECT 1 FROM members m WHERE m.id=NEW.created_by AND m.squad_id=NEW.squad_id) BEGIN INSERT OR IGNORE INTO hub_achievement_events(squad_id,member_id,metric,event_key,occurred_at) VALUES(NEW.squad_id,NEW.created_by,'marker','map:'||NEW.id,COALESCE(NEW.updated_at,strftime('%Y-%m-%dT%H:%M:%fZ','now'))); END;

INSERT OR IGNORE INTO hub_achievement_events(squad_id,member_id,metric,event_key,occurred_at) SELECT squad_id,created_by,'vehicle','map:'||id,COALESCE(updated_at,strftime('%Y-%m-%dT%H:%M:%fZ','now')) FROM squad_map_markers WHERE created_by IS NOT NULL AND 'map:'||id IS NOT NULL AND (type IN ('vehicle','car','transport') AND id NOT GLOB '*-post-[0-9]*') AND EXISTS(SELECT 1 FROM members m WHERE m.id=squad_map_markers.created_by AND m.squad_id=squad_map_markers.squad_id);

CREATE TRIGGER IF NOT EXISTS hub_ach_7_insert AFTER INSERT ON squad_map_markers WHEN NEW.created_by IS NOT NULL AND 'map:'||NEW.id IS NOT NULL AND (NEW.type IN ('vehicle','car','transport') AND NEW.id NOT GLOB '*-post-[0-9]*') AND EXISTS(SELECT 1 FROM members m WHERE m.id=NEW.created_by AND m.squad_id=NEW.squad_id) BEGIN INSERT OR IGNORE INTO hub_achievement_events(squad_id,member_id,metric,event_key,occurred_at) VALUES(NEW.squad_id,NEW.created_by,'vehicle','map:'||NEW.id,COALESCE(NEW.updated_at,strftime('%Y-%m-%dT%H:%M:%fZ','now'))); END;

INSERT OR IGNORE INTO hub_achievement_events(squad_id,member_id,metric,event_key,occurred_at) SELECT squad_id,created_by,'enemy','map:'||id,COALESCE(updated_at,strftime('%Y-%m-%dT%H:%M:%fZ','now')) FROM squad_map_markers WHERE created_by IS NOT NULL AND 'map:'||id IS NOT NULL AND (type IN ('base','enemy','enemy_base') AND id NOT GLOB '*-post-[0-9]*') AND EXISTS(SELECT 1 FROM members m WHERE m.id=squad_map_markers.created_by AND m.squad_id=squad_map_markers.squad_id);

