INSERT OR IGNORE INTO hub_achievement_events(squad_id,member_id,metric,event_key,occurred_at) SELECT squad_id,created_by,'stash','map:'||id,COALESCE(updated_at,strftime('%Y-%m-%dT%H:%M:%fZ','now')) FROM squad_map_markers WHERE created_by IS NOT NULL AND 'map:'||id IS NOT NULL AND (type='stash' AND id NOT GLOB '*-post-[0-9]*') AND EXISTS(SELECT 1 FROM members m WHERE m.id=squad_map_markers.created_by AND m.squad_id=squad_map_markers.squad_id);

CREATE TRIGGER IF NOT EXISTS hub_ach_9_insert AFTER INSERT ON squad_map_markers WHEN NEW.created_by IS NOT NULL AND 'map:'||NEW.id IS NOT NULL AND (NEW.type='stash' AND NEW.id NOT GLOB '*-post-[0-9]*') AND EXISTS(SELECT 1 FROM members m WHERE m.id=NEW.created_by AND m.squad_id=NEW.squad_id) BEGIN INSERT OR IGNORE INTO hub_achievement_events(squad_id,member_id,metric,event_key,occurred_at) VALUES(NEW.squad_id,NEW.created_by,'stash','map:'||NEW.id,COALESCE(NEW.updated_at,strftime('%Y-%m-%dT%H:%M:%fZ','now'))); END;

INSERT OR IGNORE INTO hub_achievement_events(squad_id,member_id,metric,event_key,occurred_at) SELECT squad_id,stash_checked_by,'refresh',id||':'||date(stash_checked_at,'+3 hours'),COALESCE(stash_checked_at,strftime('%Y-%m-%dT%H:%M:%fZ','now')) FROM squad_place_posts WHERE stash_checked_by IS NOT NULL AND id||':'||date(stash_checked_at,'+3 hours') IS NOT NULL AND (kind='stash' AND stash_checked_at IS NOT NULL) AND EXISTS(SELECT 1 FROM members m WHERE m.id=squad_place_posts.stash_checked_by AND m.squad_id=squad_place_posts.squad_id);

CREATE TRIGGER IF NOT EXISTS hub_ach_10_insert AFTER INSERT ON squad_place_posts WHEN NEW.stash_checked_by IS NOT NULL AND NEW.id||':'||date(NEW.stash_checked_at,'+3 hours') IS NOT NULL AND (NEW.kind='stash' AND NEW.stash_checked_at IS NOT NULL) AND EXISTS(SELECT 1 FROM members m WHERE m.id=NEW.stash_checked_by AND m.squad_id=NEW.squad_id) BEGIN INSERT OR IGNORE INTO hub_achievement_events(squad_id,member_id,metric,event_key,occurred_at) VALUES(NEW.squad_id,NEW.stash_checked_by,'refresh',NEW.id||':'||date(NEW.stash_checked_at,'+3 hours'),COALESCE(NEW.stash_checked_at,strftime('%Y-%m-%dT%H:%M:%fZ','now'))); END;

CREATE TRIGGER IF NOT EXISTS hub_ach_10_update AFTER UPDATE ON squad_place_posts WHEN NEW.stash_checked_by IS NOT NULL AND NEW.id||':'||date(NEW.stash_checked_at,'+3 hours') IS NOT NULL AND (NEW.kind='stash' AND NEW.stash_checked_at IS NOT NULL) AND EXISTS(SELECT 1 FROM members m WHERE m.id=NEW.stash_checked_by AND m.squad_id=NEW.squad_id) BEGIN INSERT OR IGNORE INTO hub_achievement_events(squad_id,member_id,metric,event_key,occurred_at) VALUES(NEW.squad_id,NEW.stash_checked_by,'refresh',NEW.id||':'||date(NEW.stash_checked_at,'+3 hours'),COALESCE(NEW.stash_checked_at,strftime('%Y-%m-%dT%H:%M:%fZ','now'))); END;

INSERT OR IGNORE INTO hub_achievement_events(squad_id,member_id,metric,event_key,occurred_at) SELECT squad_id,assignee_id,'task','task:'||id,'0000-unknown' FROM tasks WHERE assignee_id IS NOT NULL AND 'task:'||id IS NOT NULL AND (status='Выполнено') AND EXISTS(SELECT 1 FROM members m WHERE m.id=tasks.assignee_id AND m.squad_id=tasks.squad_id);

CREATE TRIGGER IF NOT EXISTS hub_ach_11_insert AFTER INSERT ON tasks WHEN NEW.assignee_id IS NOT NULL AND 'task:'||NEW.id IS NOT NULL AND (NEW.status='Выполнено') AND EXISTS(SELECT 1 FROM members m WHERE m.id=NEW.assignee_id AND m.squad_id=NEW.squad_id) BEGIN INSERT OR IGNORE INTO hub_achievement_events(squad_id,member_id,metric,event_key,occurred_at) VALUES(NEW.squad_id,NEW.assignee_id,'task','task:'||NEW.id,strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;

CREATE TRIGGER IF NOT EXISTS hub_ach_11_update AFTER UPDATE ON tasks WHEN NEW.assignee_id IS NOT NULL AND 'task:'||NEW.id IS NOT NULL AND (NEW.status='Выполнено') AND EXISTS(SELECT 1 FROM members m WHERE m.id=NEW.assignee_id AND m.squad_id=NEW.squad_id) AND OLD.status IS NOT 'Выполнено' BEGIN INSERT OR IGNORE INTO hub_achievement_events(squad_id,member_id,metric,event_key,occurred_at) VALUES(NEW.squad_id,NEW.assignee_id,'task','task:'||NEW.id,strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;


INSERT OR IGNORE INTO hub_achievement_events(squad_id,member_id,metric,event_key,occurred_at)
SELECT squad_id,member_id,'protect','protect:'||id,COALESCE(updated_at,strftime('%Y-%m-%dT%H:%M:%fZ','now')) FROM protect_updates p
WHERE member_id IS NOT NULL AND EXISTS(SELECT 1 FROM members m WHERE m.id=p.member_id AND m.squad_id=p.squad_id)
AND NOT EXISTS(SELECT 1 FROM protect_updates q WHERE q.squad_id=p.squad_id AND q.member_id=p.member_id AND julianday(q.updated_at)<julianday(p.updated_at) AND julianday(q.updated_at)>julianday(p.updated_at)-9.0/24);
CREATE TRIGGER IF NOT EXISTS hub_ach_protect AFTER INSERT ON protect_updates
WHEN NEW.member_id IS NOT NULL AND EXISTS(SELECT 1 FROM members m WHERE m.id=NEW.member_id AND m.squad_id=NEW.squad_id)
AND NOT EXISTS(SELECT 1 FROM hub_achievement_events e WHERE e.squad_id=NEW.squad_id AND e.member_id=NEW.member_id AND e.metric='protect' AND julianday(e.occurred_at)>julianday(COALESCE(NEW.updated_at,strftime('%Y-%m-%dT%H:%M:%fZ','now')))-9.0/24)
BEGIN INSERT OR IGNORE INTO hub_achievement_events(squad_id,member_id,metric,event_key,occurred_at) VALUES(NEW.squad_id,NEW.member_id,'protect','protect:'||NEW.id,COALESCE(NEW.updated_at,strftime('%Y-%m-%dT%H:%M:%fZ','now'))); END;

